namespace DrovaRandomizer.Data
{
    /// <summary>
    /// The clue art a library riddle book shows for one floor rune.
    /// Pixels are RRGGBBAA hex, rows bottom-up as SetPixels32 takes them.
    /// </summary>
    public readonly record struct FloorClueArt(int W, int H, string Hex);

    /// <summary>
    /// Floor rune key -> clue art. The contents live in FloorClueTable.g.cs, generated by
    /// tools/extract_locations/gen_floor_clue_table.py from the game's clue sprites.
    /// </summary>
    public static partial class FloorClueTable
    {
        /// <summary>
        /// The clue images of books I -> II -> III, which is also the vanilla stairs sequence of
        /// the riddle. Slot n of a shuffled sequence replaces the art of book n + 1.
        /// </summary>
        public static readonly string[] VanillaSequence = ["Energy", "Root", "Fire"];
    }
}
